import org.junit.jupiter.api.io.TempDir;

class SketchBasedJoinEstimatorDanglingMarkerTest {

	@Test
	void danglingMarkerCannotRestoreAnEvictedSnapshot(@TempDir(cleanup = CleanupMode.NEVER) Path evidence)
			throws Exception {
		var vf = SimpleValueFactory.getInstance();
		IRI predicate = vf.createIRI("urn:dangling-marker:predicate");
		List<Statement> rows = new CopyOnWriteArrayList<>();
		rows.add(vf.createStatement(vf.createIRI("urn:dangling-marker:first"), predicate, vf.createLiteral(1)));
		Path directory = evidence.resolve("synopsis");
		Path marker = directory.resolve("synopsis-v8.rebuild");
		try (SketchBasedJoinEstimator estimator = new SketchBasedJoinEstimator(
				(s, p, o, c) -> new CloseableIteratorIteration<>(rows.iterator()),
				SketchBasedJoinEstimator.Config.defaults().withMemoryBudgetBytes(4L * 1024L * 1024L))) {
			estimator.configurePersistence(directory, false);
			estimator.rebuild();
			estimator.persistIfDirty();
			Path snapshot = directory.resolve("synopsis-v8.bin");
			Path backup = evidence.resolve("original-v8-backup.bin");
			Files.copy(snapshot, backup);
			estimator.unload();
			assertEquals(0L, estimator.allocatedBytes(), "the original snapshot was evicted");
			try {
				Files.createSymbolicLink(marker, evidence.resolve("missing-target"));
			} catch (IOException | UnsupportedOperationException | SecurityException unavailable) {
				Assumptions.assumeTrue(false, "symbolic links are unavailable on this filesystem");
			}
			try {
				rows.add(vf.createStatement(vf.createIRI("urn:dangling-marker:second"), predicate,
						vf.createLiteral(2)));
				var service = estimator.synopsisService();
				QuadProbe probe = new QuadProbe(QuadProbe.PREDICATE, QuadProbe.OBJECT, 0L,
						QuadValueHash.hash(predicate), 0L, 0L, estimator.quadSnapshotIdentity());
				assertFalse(service.probe(probe).usable(), "an invalid marker must prevent stale reload");
				assertFalse(estimator.isReadyNonBlocking());
				assertTrue(service.probePublishedCurrent(probe).isEmpty());
				assertTrue(Files.isSymbolicLink(marker));
				assertEquals(-1L, Files.mismatch(snapshot, backup));
			} finally {
				if (Files.isSymbolicLink(marker)) {
					Files.move(marker, evidence.resolve("blocked-marker-symlink"));
				}
			}
		}
	}
}
